// always takes effect and is indivisible.
fn atomic_add_one() {
    loop {
        let current = C.load(Ordering::SeqCst);
        match C.compare_exchange(
            current,
            current + 1,
            Ordering::SeqCst,
            Ordering::SeqCst,
        ) {
            Ok(_) => break,
            Err(_) => {
                // Failed update attempt: retry rather than abandon.
                continue;
            }
        }
    }
}

// CIR function: main::w1
fn w1() {
    atomic_add_one();
}

// CIR function: main::w2
fn w2() {
    atomic_add_one();
}

fn main() {
