use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let mut work: i32 = 0;
    work = work + 1;
    let _ = work;
    permit.release();
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let mut work: i32 = 0;
    work = work + 1;
    let _ = work;
    permit.release();
}

