/// Worker a: takes lock a first, then lock b.
fn a(
    lock_a: Arc<Mutex<()>>,
    lock_b: Arc<Mutex<()>>,
    sa: Arc<Sem>,
    sb: Arc<Sem>,
    flag: Arc<AtomicUsize>,
